(1, 14, 7, 'RECOVERY_PLAN', 'URGENT', 'Convene Joint High-Level Taskforce between Ministry of Coal and State Revenue Authorities', 'Physical progress has stagnated at 40.5% with 7 consecutive months of risk escalation. High-level dispute resolution required for overburden disposal site.', 'RULE_ENGINE', 'ACCEPTED', '2026-08-28 21:13:17', '2026-08-28 22:48:37'),
(2, 14, 7, 'CONTRACTOR_REVIEW', 'HIGH', 'Perform Comprehensive Financial & Operational Audit of Primary EPC Contractor', 'Physical-financial gap has expanded to 21.5%, suggesting potential cash-flow diversion or contractor distress.', 'ML', 'PENDING', '2026-08-28 21:13:17', '2026-08-28 21:13:17'),
(3, 2, 8, 'SCHEDULE_REVIEW', 'HIGH', 'Restructure Sectional Commissioning Timeline for Gujarat vs Maharashtra Segments', 'Segmental opening of Vapi-Sabarmati section will allow early passenger revenue while underground civil works continue.', 'LLM', 'ACCEPTED', '2026-08-28 21:13:17', '2026-08-28 21:13:17'),
(4, 7, 13, 'COST_REVIEW', 'URGENT', 'Submit Revised Cost Estimate (RCE-I) to Public Investment Board (PIB)', 'Projected overrun of 32.0% requires formal cabinet committee approval to release escalated budgetary tranches.', 'RULE_ENGINE', 'PENDING', '2026-08-28 21:13:17', '2026-08-28 21:13:17'),
(5, 8, 14, 'MONITORING_INTENSIFICATION', 'MEDIUM', 'Deploy Bi-Weekly Drone Lidar & Digital Twin Monitoring on Underground Station Fitments', 'Will provide ground-truth verification of electrical and HVAC fitment velocity.', 'RULE_ENGINE', 'IMPLEMENTED', '2026-08-28 21:13:17', '2026-08-28 21:13:17'),
(6, 21, 25, 'ESCALATION', 'URGENT', 'Escalate Dam Safety & Hydraulic Design Verification to Central Water Commission (CWC)', 'Severe monsoon damages require specialized design modifications prior to full reservoir filling.', 'HUMAN', 'ACCEPTED', '2026-08-28 21:13:17', '2026-08-28 21:13:17');
